const evidenceLab=()=>`<section class="experience-section" id="evidence-lab"><div class="wrap"><div class="experience-intro"><p class="section-label">Interactive evidence lab</p><h2>Move through the decision.</h2><p>Scrub the timeline to see exactly which facts the agent was allowed to know.</p></div><div class="asof-lab"><div class="asof-stage"><header><span>DECISION / CREDIT-2048</span><b id="lab-state">DECISION MADE</b></header><div class="lab-question"><small>AGENT TASK</small><strong>Approve a $48,000 credit line?</strong><p id="lab-answer">Approved · risk within policy</p></div><div class="lab-facts" id="lab-facts" aria-live="polite"></div></div><aside class="asof-controls"><div><small>RECONSTRUCT AS OF</small><strong id="lab-date">09:42:11</strong></div><input id="lab-slider" type="range" min="0" max="3" value="1" aria-label="Reconstruct decision as of time"><div class="lab-ticks"><span>Input</span><span>Decision</span><span>Revision</span><span>Now</span></div><p id="lab-note">Only facts available when the decision was made are included.</p><button type="button" class="receipt-button" id="receipt-button">Generate receipt <span>↗</span></button></aside></div></div></section>`;
const evidenceJourney=()=>`<section class="experience-section journey-section"><div class="wrap"><div class="experience-intro"><p class="section-label">Follow the evidence</p><h2>One decision. A visible chain.</h2><p>Scroll through the path from raw agent activity to independent proof.</p></div><div class="journey-layout"><div class="journey-rail" aria-hidden="true"><i id="journey-progress"></i></div><div class="journey-steps"><article class="journey-step" data-journey-step><span>01 / CAPTURE</span><h3>The agent acts.</h3><p>Prompts, model calls, retrieved facts, tool results, and reviews arrive as linked OpenTelemetry spans.</p><div class="journey-signal"><i></i><i></i><i></i><i></i><b>agent.run</b></div></article><article class="journey-step" data-journey-step><span>02 / PRESERVE</span><h3>The record becomes immutable.</h3><p>Event time and system time are stored separately, preserving what was true and when it became known.</p><div class="journey-hash">7f2a <i>→</i> b91c <i>→</i> e440 <i>→</i> 18df</div></article><article class="journey-step" data-journey-step><span>03 / RECONSTRUCT</span><h3>The past opens cleanly.</h3><p>An as-of query excludes revised facts and anything that arrived after the decision.</p><div class="journey-window"><i></i><span>AS OF · 09:42:11</span></div></article><article class="journey-step" data-journey-step><span>04 / VERIFY</span><h3>The evidence leaves with proof.</h3><p>A portable receipt links the output to every source version and integrity check behind it.</p><div class="journey-verified"><span>✓</span><b>RECEIPT VERIFIED</b><small>18df…91a2</small></div></article></div></div></div></section>`;
const consolePreview=()=>`<section class="experience-section console-preview-section"><div class="wrap"><div class="experience-intro"><p class="section-label">Explore the console</p><h2>Don’t imagine it. Open it.</h2><p>A small working preview using a fictional production agent.</p></div><div class="mini-console"><aside><div class="mini-console-brand"><i></i><span>LIANS</span></div><button class="mini-nav active" type="button" data-mini-view="timeline">Timeline</button><button class="mini-nav" type="button" data-mini-view="evidence">Evidence</button><button class="mini-nav" type="button" data-mini-view="receipt">Receipt</button><small>SAMPLE WORKSPACE</small></aside><div class="mini-main"><header><div><span>underwriting-agent</span><small>Production · us-east-1</small></div><b><i></i> LIVE</b></header><div id="mini-view"></div></div></div></div></section>`;
const productLoop=()=>`<section class="section loop-section"><div class="wrap"><div class="section-head"><p class="section-label">What Lians does</p><h2>One record. Four operations.</h2></div><div class="product-loop"><article><span>01</span><h3>Record</h3><p>Every fact the agent saw, with when it was true and when you learned it.</p></article><i>→</i><article><span>02</span><h3>Reconstruct</h3><p>Reopen the decision exactly as it stood, with nothing learned later leaking in.</p></article><i>→</i><article><span>03</span><h3>Compare</h3><p>See what changed afterward, and whether it would have changed the outcome.</p></article><i>→</i><article><span>04</span><h3>Verify</h3><p>Export a receipt the recipient can check without access to your systems.</p></article></div></div></section>`;
const decisionEvidence=()=>`<section class="section numbered"><div class="wrap"><div class="numbered-head"><span>01</span><div><h2>See what the agent actually knew.</h2><ul><li>Every fact, with its source and version</li><li>Event time and ingestion time on each item</li><li>Flagged when a source was later revised</li></ul></div></div><div class="decision-view"><header><span>DECISION / RISK-1842</span><b>Evidence</b></header><div class="decision-body"><div><small>OUTPUT</small><strong>Reduce exposure by 8%</strong><p>Generated 2026-01-15 · 14:32:11 UTC</p></div><aside><small>SOURCE VERSION</small><p><b>FY26 guidance · v3</b><br>event 2026-01-12<br>ingested 2026-01-12</p><p class="revised">Revised 2026-02-04</p></aside></div></div></div></section>`;
const reconstruction=()=>`<section class="section numbered" id="demo"><div class="wrap"><div class="numbered-head"><span>02</span><div><h2>Reconstruct any past decision.</h2><ul><li>Point-in-time answers, not current ones</li><li>Future information detected and marked</li><li>Every reconstruction produces a receipt</li></ul></div></div><p class="framing">Watch a fact change, and watch the record hold.</p><div id="memory-player" aria-label="Interactive changing-facts reconstruction demo"></div></div></section>`;
const contamination=()=>`<section class="section numbered"><div class="wrap"><div class="numbered-head"><span>03</span><div><h2>Catch contamination before it costs you.</h2><ul><li>Detect facts that arrived after the decision</li><li>Compare contaminated and clean outcomes</li><li>Run it as a standing test, not a one-time audit</li></ul></div></div><div class="sharpe"><div><strong>+44%</strong><span>Sharpe · contaminated</span></div><div><strong>-4.2%</strong><span>Sharpe · honest</span></div></div><p class="artifact-note">The same losing strategy. One result quietly used facts from the future.</p></div></section>`;
const grafanaProof=()=>`<section class="section numbered"><div class="wrap"><div class="numbered-head"><span>04</span><div><h2>Fits the stack you already have.</h2><ul><li>OpenTelemetry ingestion, no migration</li><li>Evidence API and verifiable exports</li><li>Python, TypeScript, Go, Java, and MCP</li></ul></div></div><div class="grafana-panel"><header><span>LIANS / DECISION EVIDENCE</span><b>Evidence view</b></header><div class="grafana-metrics"><div><small>AS OF</small><strong id="evidence-date">2026-01-15</strong></div><div><small>DECISIONS</small><strong>184</strong></div><div><small>REVISED SOURCES</small><strong>7</strong></div></div><input id="evidence-slider" type="range" min="0" max="3" value="1" aria-label="Evidence as-of date"><div class="grafana-trace"><span>source.v3</span><i></i><span>agent.run</span><i></i><span>decision</span><i></i><span>receipt ✓</span></div></div></div></section>`;
const riad=()=>`<section class="section riad"><div class="wrap"><div class="riad-copy"><p class="section-label">RIAD-1</p><h2>We published the test, not just the result.</h2><p>RIAD-1 is an open benchmark for decision reconstruction. It runs in standing CI. Clone it, point it at any memory system including ours, and see what happens when the facts change underneath a decision that has already been made.</p><div class="hero-actions"><a class="text-link" href="/blog/locomo-benchmark">Read the benchmark →</a><a class="text-link" href="https://github.com/Lians-ai/Lians/actions" target="_blank" rel="noreferrer">Standing CI ↗</a></div></div><div class="riad-artifact" aria-label="RIAD-1 standing CI benchmark checks"><header><span>RIAD-1 / STANDING CI</span><b>RUNNING</b></header><div class="riad-run"><span>latest run</span><strong>#184</strong><small>main · reproducible</small></div><div class="riad-checks"><div><i>01</i><span>Historical reconstruction</span><b>PASS</b></div><div><i>02</i><span>Future-leak detection</span><b>PASS</b></div><div><i>03</i><span>Revision handling</span><b>PASS</b></div><div><i>04</i><span>Receipt verification</span><b>PASS</b></div></div><footer><span>4 / 4 deterministic checks</span><strong>✓</strong></footer></div></div></section>`;
const locomoProof=()=>`<section class="section locomo-proof"><div class="wrap"><div class="locomo-score" tabindex="0"><span>LOCOMO / EVIDENCE RETRIEVAL</span><strong>97.53<small>%</small></strong><p>1,498 of 1,536 answerable questions included supporting evidence.</p></div><div class="locomo-copy"><h2>Measured on a frozen, reproducible run.</h2><p>A focused check of retrieval and context compilation across the answerable LoCoMo set.</p><p class="benchmark-caveat">Evidence hit, not answer accuracy. Gold evidence was used only after retrieval for scoring.</p><a class="text-link" href="/blog/locomo-benchmark">Read the method and caveats →</a></div></div></section>`;
const notMemory=()=>`<section class="section not-memory"><div class="wrap"><p class="section-label">Governed agent memory</p><h2>Better-informed agents. Defensible decisions.</h2><p><b>Lians is a memory layer for agents that need reliable context.</b> It recalls relevant facts before an agent acts, preserves revisions instead of silently overwriting them, and records which versions shaped the result.</p><p>That can make an agent more consistent and better informed. It does not retrain the underlying model or claim to increase the model’s intelligence—and every improvement remains inspectable.</p><div class="memory-claim-grid"><div><span>01</span><b>Remember</b><small>Durable facts, preferences, and prior decisions.</small></div><div><span>02</span><b>Recall</b><small>Relevant context with validity and provenance intact.</small></div><div><span>03</span><b>Improve safely</b><small>Better context without hiding how the answer changed.</small></div></div></div></section>`;
const team=()=>`<section class="section team-section"><div class="wrap"><div class="team-heading"><h2>Built in New York.</h2></div><div class="team-grid"><a class="team-card" href="https://www.linkedin.com/in/ethanbeirne/" target="_blank" rel="noreferrer" aria-label="Ethan Beirne, CEO, on LinkedIn"><div class="team-monogram" aria-hidden="true">EB</div><div class="team-person"><h3>Ethan Beirne</h3><p>Co-founder &amp; CEO</p><span>New York · LinkedIn ↗</span></div></a><a class="team-card" href="https://www.linkedin.com/in/dereck-salazar/" target="_blank" rel="noreferrer" aria-label="Dereck Salazar, CTO, on LinkedIn"><div class="team-monogram" aria-hidden="true">DS</div><div class="team-person"><h3>Dereck Salazar</h3><p>Co-founder &amp; CTO</p><span>New York · LinkedIn ↗</span></div></a></div></div></section>`;
const cohort=()=>`<section class="cta-section pricing-close"><div class="wrap"><div class="pricing-close-copy"><h2>One production workflow. Eight weeks.</h2><p>Bring one regulated AI workflow. We instrument its evidence path and deliver a reconstruction and verification package your team can review.</p><p>No cohort cap. No artificial deadline. If the scope changes, you approve the price before work begins.</p></div><div class="pricing-close-card"><span>Implementation</span><strong>$25,000</strong><p>Fixed scope · eight weeks</p><a class="button button-primary" href="/design-partners">Plan your implementation →</a></div></div></section>`;
