const pageShell=(body)=>`<section class="page-hero"><div class="wrap page-hero-grid"><div><h1>${page.title}</h1><p class="lede">${page.lede}</p></div><div class="page-geometry" data-shape="${page.type}" aria-label="${geometryLabels[page.type]||"A geometric evidence lattice"}"><canvas class="page-geometry-canvas"></canvas></div></div></section>${body}${page.type==="pilot"?"":cta()}`;
const product=()=>pageShell(`<section class="story-system"><div class="wrap">
  <article class="story-row"><div class="story-copy"><span>01 / CAPTURE</span><h2>Capture the full execution path.</h2><p>Lians receives OpenTelemetry spans from agents, model calls, tools, retrieval, and human review. GenAI attributes remain queryable instead of disappearing into flattened logs.</p></div><div class="evidence-artifact trace-artifact" aria-label="A linked AI execution trace"><header><span>RUN / 1842</span><b>4 LINKED EVENTS</b></header><div><time>14:32:08</time><i></i><strong>agent.run</strong><em>recorded</em></div><div><time>14:32:09</time><i></i><strong>model.response</strong><em>linked</em></div><div><time>14:32:10</time><i></i><strong>tool.execute</strong><em>preserved</em></div><div><time>14:32:11</time><i></i><strong>human.review</strong><em>verified</em></div></div></article>
  <article class="story-row reverse"><div class="story-copy"><span>02 / PRESERVE</span><h2>Make the record durable.</h2><p>Each event is linked to a governed history with event time, system time, provenance, review state, and integrity verification. You can reconstruct what the system knew at the time, not only what is true now.</p></div><div class="evidence-artifact clock-artifact" aria-label="Event time and system time record"><header><span>FACT / REVENUE</span><b>VERSION HISTORY</b></header><div class="clock-axis"><small>EVENT TIME</small><i></i><strong>2026-01-12</strong></div><div class="clock-axis"><small>SYSTEM TIME</small><i></i><strong>2026-01-15</strong></div><footer><span>v3</span><p>FY26 guidance · source preserved</p><b>HASH 18DF</b></footer></div></article>
  <article class="story-row"><div class="story-copy"><span>03 / RECONSTRUCT</span><h2>Reconstruct the decision.</h2><p>Query the evidence record as it existed at any prior moment and keep later information out of the result.</p></div><div class="evidence-artifact window-artifact" aria-label="A point-in-time reconstruction window"><header><span>AS OF / 14:32:11</span><b>HISTORICAL VIEW</b></header><div class="window-track"><i></i><span>DECISION</span><em>REVISION EXCLUDED</em></div><div class="window-facts"><p><i></i>Identity verified <b>KNOWN</b></p><p><i></i>Guidance v3 <b>KNOWN</b></p><p class="future"><i></i>Guidance v4 <b>FUTURE</b></p></div></div></article>
  <article class="story-row reverse"><div class="story-copy"><span>04 / VERIFY</span><h2>Produce proof.</h2><p>Export linked events and integrity data for incident review, model validation, legal discovery, or regulatory response.</p></div><div class="evidence-artifact receipt-artifact" aria-label="A verified decision receipt"><div class="receipt-mark">✓</div><span>DECISION RECEIPT</span><h3>Verification passed.</h3><dl><div><dt>Decision</dt><dd>risk-1842</dd></div><div><dt>Sources</dt><dd>3 linked</dd></div><div><dt>Chain</dt><dd>18df…91a2</dd></div></dl></div></article>
</div></section>`);
