const about=()=>pageShell(`<section class="story-system about-system"><div class="wrap">
  <article class="story-row"><div class="story-copy"><span>THE GAP</span><h2>Observability shows signals. Lians preserves proof.</h2><p>Teams already have dashboards, traces, and alerts. What they lack is a durable way to reconstruct the exact context behind an AI action and prove that record later.</p></div><div class="evidence-artifact compare-artifact" aria-label="Difference between observability and evidence"><header><span>SIGNAL</span><b>RECORD</b></header><div><p>Latency spike</p><i>→</i><p>Exact run</p></div><div><p>Model error</p><i>→</i><p>Source versions</p></div><div><p>Alert</p><i>→</i><p>Verifiable receipt</p></div><footer>SEE WHAT HAPPENED <i>→</i> PROVE WHY</footer></div></article>
  <article class="story-row reverse"><div class="story-copy"><span>THE FOCUS</span><h2>That is the one problem Lians solves.</h2><p>We connect production telemetry to governed evidence so engineering, operations, risk, and compliance can work from the same history.</p></div><div class="evidence-artifact flow-artifact" aria-label="Lians evidence flow"><div><span>01</span><b>AI action</b><small>Agent and tool traces</small></div><i>→</i><div><span>02</span><b>Governed record</b><small>Time and provenance</small></div><i>→</i><div><span>03</span><b>Proof</b><small>Replay and receipt</small></div></div></article>
  <article class="story-row"><div class="story-copy"><span>THE BOUNDARY</span><h2>Open at the edges.</h2><p>Lians is OpenTelemetry-native, open source, API-accessible, and self-hostable.</p></div><div class="evidence-artifact edge-artifact" aria-label="Open integration boundaries"><div class="edge-core"><img src="/logo-blue.png" alt="Lians"></div><span class="edge-node edge-node-a" aria-label="OTLP: Send OpenTelemetry traces from agents, models, tools, and retrieval systems.">OTLP<span class="edge-tip" aria-hidden="true">Send OpenTelemetry traces from agents, models, tools, and retrieval systems.</span></span><span class="edge-node edge-node-b" aria-label="API: Write, query, and reconstruct governed evidence through a focused API.">API<span class="edge-tip" aria-hidden="true">Write, query, and reconstruct governed evidence through a focused API.</span></span><span class="edge-node edge-node-c" aria-label="Export: Produce portable evidence and verifiable receipts for review.">EXPORT<span class="edge-tip" aria-hidden="true">Produce portable evidence and verifiable receipts for review.</span></span><span class="edge-node edge-node-d" aria-label="Self-host: Keep the evidence boundary inside infrastructure you control.">SELF-HOST<span class="edge-tip" aria-hidden="true">Keep the evidence boundary inside infrastructure you control.</span></span></div></article>
</div></section>`);
const pilot=()=>pageShell(`<div class="wrap content-grid"><aside class="toc">ONE WORKFLOW<br>ONE EVIDENCE PATH<br>4–8 WEEKS</aside><main class="prose"><h2>Bring us one workflow that needs a defensible record.</h2><p>We map its AI execution path, instrument OpenTelemetry, configure the Grafana view, and verify that Lians can reconstruct the evidence behind a production event.</p><form class="pilot-form" id="partner-application"><div class="form-grid"><label>Work email<input type="email" name="work_email" autocomplete="email" required></label><label>Company<input name="company" autocomplete="organization" required></label><label>Role<input name="role" autocomplete="organization-title" required></label><label>Company website<input type="url" name="company_website" placeholder="https://" required></label></div><label>What does the AI workflow do?<textarea name="agent_workflow" required></textarea></label><label>Which inputs, policies, or facts can change?<textarea name="changing_facts" required></textarea></label><label>What must your team reconstruct or prove?<textarea name="audit_requirement" required></textarea></label><div class="form-grid"><label>Current stage<select name="current_stage" required><option value="">Select one</option><option>Prototype</option><option>Pilot</option><option>Production</option></select></label><label>Preferred engagement<select name="preferred_track" required><option value="">Select one</option><option>Implementation</option><option>Evaluation</option><option>Unsure</option></select></label><label>Deployment requirement<select name="deployment_requirement" required><option value="">Select one</option><option>Cloud</option><option>Private cloud</option><option>Self-hosted</option><option>Air-gapped</option></select></label><label>Architecture or example (optional)<input type="file" name="architecture_file" accept=".pdf,.txt,.md,.png,.jpg,.jpeg"></label></div><input type="hidden" name="utm_source"><input type="hidden" name="utm_medium"><input type="hidden" name="utm_campaign"><input type="hidden" name="utm_term"><input type="hidden" name="utm_content"><input type="hidden" name="landing_page"><input type="hidden" name="referring_url"><div class="hero-actions"><button class="button button-primary" type="submit">Apply for a focused pilot →</button><span id="partner-form-status" role="status"></span></div></form><div id="partner-form-success" hidden><h3>Application received.</h3><p>We will review the workflow and reply with a direct fit assessment.</p><a id="partner-booking-link" hidden>Schedule a fit call →</a></div></main></div>`);
